// custom-worker.ts
// @ts-ignore generated by opennextjs-cloudflare build
import { default as handler } from "./.open-next/worker.js";

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    if (typeof process !== "undefined" && process.env) {
      Object.assign(process.env, env);
    }
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_event: ScheduledEvent, env: CloudflareEnv, ctx: ExecutionContext) {
    if (typeof process !== "undefined" && process.env) {
      Object.assign(process.env, env);
    }
    const req = new Request("https://ruxs.in/api/cron/tick", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(req, env, ctx)).then(
        (res: Response) => {
          if (!res.ok) console.error(`[scheduled] cron tick returned HTTP ${res.status}`);
        },
        (err: unknown) => {
          console.error("[scheduled] cron tick failed", err);
        }
      )
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
